// Decide se uma PESSOA esta no comando desta conversa.
//
// Dois sinais, nesta ordem:
//   1) a conversa tem responsavel (assignee)  -> silencio enquanto durar
//   2) a ultima resposta saiu do proprio Chatwoot, escrita por gente
//      -> silencio por JANELA_MIN minutos
//
// Como separar a IA de um humano: a Datafy espelha a resposta que a IA
// mandou pelo WhatsApp marcando content_attributes.from_echo = true.
// Mensagem escrita DENTRO do Chatwoot nao tem essa marca.
//
// FALHA ABERTA: qualquer erro devolve humano=false, para a IA nunca
// emudecer por causa de um servico auxiliar.

const JANELA_MIN = 60;

const corpo = $('Webhook').first().json.body || {};
const tel = String(corpo.telefone || '').replace(/\D/g, '');
const fim = tel.slice(-8);

let humano = false;
let motivo = 'ninguem da equipe esta nesta conversa';

try {
  const entrada = $input.first().json || {};

  if (entrada.error) {
    motivo = 'Chatwoot nao respondeu; seguindo com a IA';
  } else if (!fim) {
    motivo = 'telefone ausente no webhook; seguindo com a IA';
  } else {
    const lista = (entrada.data && entrada.data.payload) || [];
    const conversa = lista.find((c) => {
      const s = (c.meta && c.meta.sender && c.meta.sender.phone_number) || '';
      return String(s).replace(/\D/g, '').endsWith(fim);
    });

    if (!conversa) {
      motivo = 'sem conversa aberta no Chatwoot para este telefone';
    } else if (conversa.meta && conversa.meta.assignee && conversa.meta.assignee.id) {
      humano = true;
      motivo = 'conversa ' + conversa.id + ' esta com ' + conversa.meta.assignee.name;
    } else {
      const msgs = conversa.messages || [];
      const saidas = msgs.filter(
        (m) => m.message_type === 1 && m.sender && m.sender.type === 'user',
      );
      const ultima = saidas[saidas.length - 1];

      if (ultima) {
        const atrib = ultima.content_attributes || {};
        const ecoDaIa = atrib.from_echo === true;
        if (!ecoDaIa) {
          const quando = Number(ultima.created_at || 0) * 1000;
          const minutos = quando ? (Date.now() - quando) / 60000 : 0;
          if (!quando || minutos <= JANELA_MIN) {
            humano = true;
            motivo =
              'alguem da equipe respondeu pelo Chatwoot ha ' + Math.round(minutos) + ' min';
          } else {
            motivo =
              'a ultima resposta humana foi ha ' + Math.round(minutos) + ' min; a IA reassume';
          }
        } else {
          motivo = 'a ultima resposta foi da propria IA';
        }
      }
    }
  }
} catch (e) {
  humano = false;
  motivo = 'falha ao consultar o Chatwoot (' + e.message + '); seguindo com a IA';
}

return [{ json: { humano, motivo, telefone: tel, quando: new Date().toISOString() } }];
